/**
 * @param {number[]} temperatures
 * @return {number[]}
 */
function daily(temperatures = [73, 74, 75, 71, 69, 72, 76, 73]) {
    let answers = Array(temperatures.length).fill(0), i = 0, start = 0;

    while (i + 1 <= temperatures.length) {
        if (temperatures[i] > temperatures[start]) {
            answers[start] = i - start;
            start++;
            i = start;
        } else {
            i++;
        }
    }

    return answers;
}

console.log(daily());
